INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'gateway', 'n.', '/ˈɡeɪtweɪ/', '门户;通道', 'On the Silk Road, Dunhuang was the gateway to and from ancient China.', '在丝绸之路上,敦煌是进出古代中国的门户。', 'Welcome to Dunhuang', 1, 0, 'senior', 'wordlist', 'elective4', 'U3', 'the gateway to', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'oasis', 'n.', '/əʊˈeɪsɪs/', '(沙漠中的)绿洲', 'Tired travellers were glad to see the green oasis of Dunhuang ahead of them.', '疲惫的旅人很高兴看到前方敦煌这片绿洲。', 'Welcome to Dunhuang', 2, 0, 'senior', 'wordlist', 'elective4', 'U3', 'a green oasis', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'glorious', 'adj.', '/ˈɡlɔːriəs/', '辉煌的;壮丽的', 'Dunhuang has a long and glorious history as a centre of exchange.', '敦煌作为交流中心,有着悠久而辉煌的历史。', 'Welcome to Dunhuang', 3, 0, 'senior', 'wordlist', 'elective4', 'U3', 'a glorious history', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'boast', 'v.', '/bəʊst/', '(地方等)自豪地拥有;夸耀', 'The city boasts many sites with UNESCO-protected heritage status.', '这座城市自豪地拥有许多受联合国教科文组织保护的遗产地。', 'Welcome to Dunhuang', 4, 0, 'senior', 'wordlist', 'elective4', 'U3', 'boast heritage sites', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'grotto', 'n.', '/ˈɡrɒtəʊ/', '小洞穴;岩洞', 'The Mogao Grottoes were carved out of the rock over a thousand years.', '莫高窟是历经千年从岩石中开凿出来的。', 'Welcome to Dunhuang', 5, 0, 'senior', 'wordlist', 'elective4', 'U3', 'the Mogao Grottoes', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'testimony', 'n.', '/ˈtestɪməni/', '证据;证明', 'The paintings are a testimony to how the Silk Road brought East and West together.', '这些画作证明了丝绸之路如何把东西方联系在一起。', 'Welcome to Dunhuang', 6, 0, 'senior', 'wordlist', 'elective4', 'U3', 'a testimony to', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'statue', 'n.', '/ˈstætʃuː/', '雕像;塑像', 'These statues show elements from Ancient Greece, India and Iran.', '这些雕像融合了古希腊、印度和伊朗的元素。', 'Welcome to Dunhuang', 7, 0, 'senior', 'wordlist', 'elective4', 'U3', 'ancient statues', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'mural', 'n.', '/ˈmjʊərəl/', '壁画', 'The murals cover an astonishing area of the cave walls.', '这些壁画覆盖了洞窟墙壁惊人的面积。', 'Welcome to Dunhuang', 8, 0, 'senior', 'wordlist', 'elective4', 'U3', 'colourful murals', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'religious', 'adj.', '/rɪˈlɪdʒəs/', '宗教的', 'The subjects of the murals vary from religious stories to everyday life.', '壁画的题材从宗教故事到日常生活,各不相同。', 'Welcome to Dunhuang', 9, 0, 'senior', 'wordlist', 'elective4', 'U3', 'religious stories', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'immortal', 'n.', '/ɪˈmɔːtl/', '神;(adj.)不朽的', 'The Apsaras are also called the Flying Immortals.', '飞天也被称作“飞行的神仙”。', 'Welcome to Dunhuang', 10, 0, 'senior', 'wordlist', 'elective4', 'U3', 'the Flying Immortals', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'heavenly', 'adj.', '/ˈhevnli/', '天国的;天空的', 'These heavenly musicians and dancers decorate the walls of many caves.', '这些天国的乐师和舞者装饰着许多洞窟的墙壁。', 'Welcome to Dunhuang', 11, 0, 'senior', 'wordlist', 'elective4', 'U3', 'heavenly musicians', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'peak', 'n.', '/piːk/', '高峰,顶点;山峰', 'The painting of Apsaras reached a peak during the Tang Dynasty.', '飞天绘画在唐代达到了顶峰。', 'Welcome to Dunhuang', 12, 0, 'senior', 'wordlist', 'elective4', 'U3', 'reach a peak', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'scroll', 'n.', '/skrəʊl/', '纸卷,卷轴', 'The scrolls describe the wide range of goods traded along the Silk Road.', '这些卷轴描述了丝绸之路上交易的各种货物。', 'Welcome to Dunhuang', 13, 0, 'senior', 'wordlist', 'elective4', 'U3', 'ancient scrolls', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'ceramics', 'n.', '/səˈræmɪks/', '陶瓷制品', 'Goods such as ceramics and medicine passed through Dunhuang.', '陶瓷和药材等货物曾途经敦煌。', 'Welcome to Dunhuang', 14, 0, 'senior', 'wordlist', 'elective4', 'U3', 'fine ceramics', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'crossroads', 'n.', '/ˈkrɒsrəʊdz/', '汇集地;交叉路口', 'Dunhuang has once again become a global crossroads.', '敦煌再次成为一个全球汇集地。', 'Welcome to Dunhuang', 15, 0, 'senior', 'wordlist', 'elective4', 'U3', 'a global crossroads', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'expo', 'n.', '/ˈekspəʊ/', '展览会,博览会', 'Dunhuang hosted the Silk Road International Cultural Expo in 2017.', '敦煌于2017年举办了丝绸之路国际文化博览会。', 'Welcome to Dunhuang', 16, 0, 'senior', 'wordlist', 'elective4', 'U3', 'the Silk Road Expo', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'strengthen', 'v.', '/ˈstreŋθn/', '加强', 'The Expo aimed to strengthen cooperation between countries along the route.', '博览会旨在加强沿线国家之间的合作。', 'Welcome to Dunhuang', 17, 0, 'senior', 'wordlist', 'elective4', 'U3', 'strengthen cooperation', NULL, 'fltrp');
