INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'institute', 'n.', '/ˈɪnstɪtjuːt/', '学院;研究院', 'The Confucius Institute promotes Chinese language and culture abroad.', '孔子学院在海外推广汉语和中国文化。', 'Welcome to Dunhuang', 21, 0, 'senior', 'wordlist', 'elective4', 'U3', 'the Confucius Institute', NULL, 'fltrp');
