INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'trade', 'n./v.', '/treɪd/', '贸易;交易', 'When the trade routes changed, the city became far less busy.', '当贸易路线改变后,这座城市远不如从前繁忙。', 'Welcome to Dunhuang', 39, 0, 'senior', 'wordlist', 'elective4', 'U3', 'the trade routes', NULL, 'fltrp');
