INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'manuscript', 'n.', '/ˈmænjuskrɪpt/', '手稿,手抄本', 'Thousands of manuscripts were hidden inside the Library Cave.', '成千上万的手稿藏在藏经洞内。', 'Welcome to Dunhuang', 44, 0, 'senior', 'wordlist', 'elective4', 'U3', 'ancient manuscripts', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'significance', 'n.', '/sɪɡˈnɪfɪkəns/', '重要性,意义', 'Its long history shows the significance of Dunhuang on the Silk Road.', '悠久的历史显示出敦煌在丝绸之路上的重要性。', 'Welcome to Dunhuang', 45, 0, 'senior', 'wordlist', 'elective4', 'U3', 'great significance', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'destination', 'n.', '/ˌdestɪˈneɪʃn/', '目的地', 'Today Dunhuang is a world-class tourist destination.', '如今敦煌是世界级的旅游目的地。', 'Welcome to Dunhuang', 46, 0, 'senior', 'wordlist', 'elective4', 'U3', 'a tourist destination', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'mutual', 'adj.', '/ˈmjuːtʃuəl/', '相互的,共同的', 'The Expo aimed to strengthen mutual cooperation between countries.', '博览会旨在加强国家之间的相互合作。', 'Welcome to Dunhuang', 47, 0, 'senior', 'wordlist', 'elective4', 'U3', 'mutual cooperation', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'cooperation', 'n.', '/kəʊˌɒpəˈreɪʃn/', '合作', 'Countries along the route built closer cooperation through the Expo.', '沿线国家通过博览会建立了更紧密的合作。', 'Welcome to Dunhuang', 48, 0, 'senior', 'wordlist', 'elective4', 'U3', 'close cooperation', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'prosperous', 'adj.', '/ˈprɒspərəs/', '繁荣的,富裕的', 'Dunhuang was once a prosperous city on the trade route.', '敦煌曾是贸易路线上一座繁荣的城市。', 'Welcome to Dunhuang', 49, 0, 'senior', 'wordlist', 'elective4', 'U3', 'a prosperous city', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'promote', 'v.', '/prəˈməʊt/', '促进,推广', 'The theme of the Expo was to promote cultural exchange.', '博览会的主题是促进文化交流。', 'Welcome to Dunhuang', 50, 0, 'senior', 'wordlist', 'elective4', 'U3', 'promote exchange', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe4u3.01', '①时间与条件状语从句(when/while/as/until/before/after/as soon as · if/unless/as long as/in case)', 'A2', 12, '外研社版选择性必修第四册 U3 — 看从句与主句的逻辑:先后或同时发生用时间连词(when 当…时、while/as 在…期间、until 直到、as soon as 一…就);提出前提或条件用条件连词(if 如果、unless 除非、as long as 只要、in case 以防)。', 1, 'elective4', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe4u3.02', '②让步与原因状语从句(though/although/even though/while · because/since/as/now that)', 'A2', 12, '外研社版选择性必修第四册 U3 — 前后有“转折让步”关系用让步连词(although/though/even though 虽然、while 尽管/而);前后是“因为—所以”的原因关系用原因连词(because/since/as 因为、now that 既然)。', 2, 'elective4', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe4u3.03', '③结果·目的·方式状语从句(so…that/such…that · so that/in order that · as if/as though)', 'A2', 12, '外研社版选择性必修第四册 U3 — “如此…以致于”的结果用 so+形容词/副词+that 或 such+(a/an)+名词+that;表“为了”的目的用 so that / in order that;表“仿佛、好像”的方式用 as if / as though。', 3, 'elective4', 'U3', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.01'), '____ travellers finally reached Dunhuang, they saw the green oasis ahead of them.', 'When', 'Unless', 'In case', 'As if', 'A', '句意:旅人到达敦煌时看见绿洲,前后是同时发生的时间关系 → When。其余连词使句意不通。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.01'), '____ the guide entered the dark cave, she turned on her torch to show us the murals.', 'Unless', 'As soon as', 'In case', 'As though', 'B', '句意:导游一进洞就打开手电,“一…就”用 As soon as。其余使句意不通。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.01'), '____ we were walking through the grottoes, our guide explained the history of the Silk Road.', 'Unless', 'In case', 'While', 'As if', 'C', '句意:走过洞窟“期间”导游讲解,表同时进行 → While。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.01'), 'The murals stayed hidden ____ a Taoist priest discovered the sealed Library Cave in 1900.', 'unless', 'because', 'as long as', 'until', 'D', '句意:壁画一直藏到道士发现藏经洞为止,表“直到”→ until。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.01'), 'The caves had been carved for centuries ____ the Tang Dynasty reached its golden age.', 'before', 'unless', 'although', 'in case', 'A', '句意:洞窟开凿在唐代鼎盛“之前”已持续数百年,表先后 → before。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.01'), '____ the trade routes changed, Dunhuang slowly faded from people''s memory.', 'Unless', 'After', 'In case', 'As if', 'B', '句意:贸易路线改变“之后”敦煌渐被遗忘,表先后时间 → After。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.01'), '____ the years passed, Dunhuang grew into a world-class tourist destination.', 'Unless', 'In case', 'As', 'As if', 'C', '句意:随着岁月流逝敦煌逐渐发展,表“随着”→ As。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.01'), '____ night fell over the desert, the temperature around Dunhuang dropped very quickly.', 'Unless', 'In case', 'As if', 'When', 'D', '句意:夜幕降临“时”气温骤降,表时间 → When。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.01'), '____ the museum opens each morning, visitors hurry to see the famous Flying Apsaras.', 'As soon as', 'Unless', 'Although', 'In case', 'A', '句意:博物馆一开门游客就赶去看飞天,“一…就”→ As soon as。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.01'), 'Keep walking forward ____ you reach the wall covered with thousands of tiny Buddhas.', 'unless', 'until', 'although', 'in case', 'B', '句意:一直往前走直到到达那面墙,表“直到”→ until。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.01'), '____ you look up, you can see the colourful paintings on the ceiling of the cave.', 'Unless', 'Although', 'If', 'So that', 'C', '句意:你若抬头就能看到壁画,前后是条件关系 → If。其余连词使句意矛盾或不通。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.01'), '____ you book a ticket in advance, you will not be allowed into the Mogao Grottoes.', 'Although', 'Because', 'As if', 'Unless', 'D', '句意:除非提前订票,否则不准进入,“除非”→ Unless。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.01'), 'You may take photos in the cave ____ you do not use a flash.', 'as long as', 'unless', 'although', 'because', 'A', '句意:只要不用闪光灯就可以拍照,表“只要”→ as long as。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.01'), 'Take a bottle of water with you ____ you feel thirsty in the dry desert air.', 'unless', 'in case', 'although', 'so that', 'B', '句意:带瓶水以防口渴,表“以防”→ in case。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.01'), '____ the weather is good tomorrow, we will climb the Mingsha Mountain near Dunhuang.', 'Unless', 'Although', 'If', 'As if', 'C', '句意:如果明天天气好就去爬鸣沙山,表条件 → If。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.01'), 'Visitors cannot understand the murals well ____ a guide explains the old stories to them.', 'although', 'because', 'as if', 'unless', 'D', '句意:除非导游讲解,否则游客看不懂壁画,“除非”→ unless。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.01'), '____ you keep your voice low, you are welcome to stay and enjoy the wall paintings.', 'As long as', 'Unless', 'Although', 'Because', 'A', '句意:只要小声说话就欢迎你留下,表“只要”→ As long as。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.01'), 'The team made careful copies of the scrolls ____ the fragile originals were ever damaged.', 'unless', 'in case', 'although', 'so that', 'B', '句意:复制卷轴以防原件受损,表“以防”→ in case。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.01'), '____ you visit Dunhuang in summer, remember to bring a hat against the strong sun.', 'Unless', 'Although', 'If', 'As if', 'C', '句意:如果夏天去敦煌记得带帽子,表条件 → If。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.01'), 'The ancient city would not have grown rich ____ the Silk Road had passed through it.', 'although', 'because', 'as long as', 'unless', 'D', '句意:要不是丝绸之路经过,这座城不会富裕,“除非/要不是”→ unless。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.02'), '____ Dunhuang was once such a great city, it gradually faded from memory.', 'Although', 'Because', 'If', 'Until', 'A', '句意:敦煌虽曾辉煌,却逐渐被遗忘,前后转折 → Although。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.02'), '____ the desert journey was dangerous, many traders still crossed it to reach Dunhuang.', 'Because', 'Even though', 'As soon as', 'Unless', 'B', '句意:尽管旅程危险,商人仍穿越,前后让步 → Even though。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.02'), 'The Library Cave is small, ____ it once held thousands of priceless manuscripts.', 'because', 'so that', 'though', 'as soon as', 'C', '句意:藏经洞虽小,却藏过无数珍贵手稿,转折 → though。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.02'), '____ some murals show religious stories, others picture the daily life of ordinary people.', 'Because', 'If', 'Until', 'While', 'D', '句意:有些壁画画宗教故事,而另一些画日常生活,表对比让步 → While。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.02'), '____ the paintings are over a thousand years old, their colours are still surprisingly bright.', 'Although', 'Because', 'As long as', 'So that', 'A', '句意:画作虽逾千年,色彩依旧鲜亮,前后转折 → Although。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.02'), 'Visitors keep coming to the grottoes, ____ the tickets are not at all cheap.', 'because', 'even though', 'in case', 'as soon as', 'B', '句意:尽管门票不便宜,游客仍络绎不绝,让步 → even though。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.02'), '____ he was only a poor Taoist priest, his discovery changed the study of the Silk Road.', 'Because', 'Unless', 'Though', 'As if', 'C', '句意:他虽只是个穷道士,其发现却改变了丝路研究,转折 → Though。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.02'), '____ the north of the city was busy with trade, the southern caves stayed quiet and holy.', 'Because', 'If', 'Until', 'While', 'D', '句意:城北忙于贸易,而城南洞窟静谧神圣,表对比让步 → While。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.02'), '____ the trade routes had moved far away, Dunhuang never lost its cultural treasures.', 'Although', 'As soon as', 'Because', 'Unless', 'A', '句意:贸易路线虽已远去,敦煌仍未失去文化珍宝,转折 → Although。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.02'), 'The artists kept painting the Flying Apsaras, ____ the work took many years to finish.', 'because', 'even though', 'so that', 'as long as', 'B', '句意:尽管要画很多年,画师们仍坚持创作飞天,让步 → even though。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.02'), 'The Expo chose Dunhuang ____ it had long been a meeting point of East and West.', 'although', 'unless', 'because', 'so that', 'C', '句意:博览会选敦煌是因为它长期是东西方交汇点,表原因 → because。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.02'), '____ Dunhuang sits on the old Silk Road, it became a great centre of cultural exchange.', 'Although', 'Unless', 'While', 'Since', 'D', '句意:因为敦煌位于古丝路上,它成了文化交流中心,表原因 → Since。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.02'), '____ the Belt and Road brings life back to the Silk Road, Dunhuang is busy once again.', 'Now that', 'Although', 'Unless', 'As if', 'A', '句意:既然“一带一路”让丝路重焕生机,敦煌再度繁忙,表原因 → Now that。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.02'), 'Many scholars study the old scrolls ____ they reveal how different communities once lived.', 'although', 'because', 'if', 'until', 'B', '句意:学者研究卷轴是因为它们揭示了过去的生活,表原因 → because。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.02'), '____ the murals are very fragile, the staff keep the light inside the caves quite low.', 'Although', 'Unless', 'Since', 'So that', 'C', '句意:因为壁画十分脆弱,工作人员把洞内光线调暗,表原因 → Since。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.02'), '____ you have seen the statues, let us move on to the famous Library Cave.', 'Although', 'Unless', 'As if', 'Now that', 'D', '句意:既然你已看过雕像,我们就去藏经洞,表原因 → Now that。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.02'), 'Dunhuang grew rich ____ goods from as far away as Europe arrived through its gates.', 'because', 'although', 'unless', 'while', 'A', '句意:敦煌富裕是因为远至欧洲的货物经此进入,表原因 → because。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.02'), '____ very few records survive, the reason the cave was sealed remains a mystery.', 'Unless', 'Since', 'In case', 'So that', 'B', '句意:因为留存的记录极少,封洞之因仍是谜,表原因 → Since。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.02'), '____ the city has become a global crossroads, people from many countries come to visit it.', 'Although', 'Unless', 'Now that', 'Until', 'C', '句意:既然这座城已成全球汇集地,各国游客纷至,表原因 → Now that。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.02'), 'The guide spoke slowly ____ the long history of the caves was hard to take in all at once.', 'although', 'if', 'as soon as', 'because', 'D', '句意:导游讲得慢是因为洞窟的悠久历史一时难以消化,表原因 → because。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.03'), 'The desert sun was ____ strong that we needed both hats and plenty of water.', 'so', 'such', 'very', 'too', 'A', '“so + 形容词 + that”引导结果状语从句:so strong that → so。such 接名词、very/too 不能引出 that 结果从句。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.03'), 'Dunhuang was ____ a busy crossroads that goods came to it from all over Asia.', 'so', 'such', 'very', 'too', 'B', '“such + a + 名词 + that”引导结果从句:such a busy crossroads that → such。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.03'), 'The cave was ____ dark that we could hardly see the murals at first.', 'such', 'very', 'so', 'quite', 'C', '“so + 形容词 + that”:so dark that → so。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.03'), 'The Library Cave held ____ amazing treasures that scholars still study them today.', 'so', 'very', 'too', 'such', 'D', '“such + 名词(复数)+ that”:such amazing treasures that → such。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.03'), 'The colours have lasted ____ long that it is hard to believe their true age.', 'so', 'such', 'very', 'too', 'A', '“so + 副词 + that”:so long that → so。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.03'), 'It is ____ a famous site that thousands of tourists arrive every single day.', 'so', 'such', 'very', 'too', 'B', '“such + a + 名词 + that”:such a famous site that → such。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.03'), 'The statues are ____ lifelike that they almost seem ready to speak.', 'such', 'very', 'so', 'too', 'C', '“so + 形容词 + that”:so lifelike that → so。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.03'), 'Come a little closer ____ you can see the fine details of the painting.', 'because', 'even though', 'as if', 'so that', 'D', '句意:走近些“以便”看清细节,表目的 → so that。其余连词使句意不通。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.03'), 'The team copied the scrolls ____ future students could still read them one day.', 'in order that', 'because', 'although', 'as though', 'A', '句意:复制卷轴“为了”后人仍能阅读,表目的 → in order that。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.03'), 'The city built rest houses ____ tired traders could sleep safely at night.', 'because', 'so that', 'unless', 'as if', 'B', '句意:建驿站“以便”疲惫的商人安睡,表目的 → so that。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.03'), 'The lights are kept low ____ the ancient colours of the murals do not fade away.', 'because', 'although', 'in order that', 'as if', 'C', '句意:灯光调暗“为了”古老色彩不褪去,表目的 → in order that。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.03'), 'The Expo was held in Dunhuang ____ countries along the Silk Road could work together.', 'because', 'even though', 'as though', 'so that', 'D', '句意:博览会在敦煌举办“以便”沿线国家合作,表目的 → so that。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.03'), 'Our guide spoke loudly ____ everyone standing inside the cave could hear the story.', 'so that', 'because', 'although', 'as if', 'A', '句意:导游大声讲“以便”洞内所有人都能听见,表目的 → so that。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.03'), 'Clear signs are placed everywhere ____ no visitor gets lost among the many caves.', 'because', 'in order that', 'unless', 'as though', 'B', '句意:到处设清晰指示牌“为了”游客不迷路,表目的 → in order that。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.03'), 'The dancers in the mural move ____ they can really hear the music in the air.', 'even if', 'so that', 'as if', 'now that', 'C', '句意:壁画中的舞者动作“仿佛”真能听见音乐,表方式 → as if。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.03'), 'The painted figures look ____ they are floating freely in the bright blue sky.', 'even though', 'so that', 'in case', 'as though', 'D', '句意:画中人物看起来“好像”在蓝天里飘浮,表方式 → as though。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.03'), 'She described the ancient city ____ she had walked through its streets herself.', 'as if', 'even if', 'because', 'so that', 'A', '句意:她描述古城“仿佛”亲自走过,表方式 → as if。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.03'), 'The empty Library Cave felt ____ it were still keeping an ancient secret.', 'even though', 'as though', 'so that', 'now that', 'B', '句意:空荡的藏经洞感觉“好像”仍守着古老的秘密,表方式 → as though。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.03'), 'The guide waved her torch ____ she were painting the dark air with light.', 'even if', 'because', 'as if', 'in order that', 'C', '句意:导游挥动手电“仿佛”在用光作画,表方式 → as if。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U3' AND code='fe4u3.03'), 'The tired travellers stared at the oasis ____ it were a beautiful dream.', 'even though', 'so that', 'now that', 'as though', 'D', '句意:疲惫的旅人凝望绿洲“好像”那是个美梦,表方式 → as though。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'The Mogao Grottoes', 'On the edge of the desert near Dunhuang stand the Mogao Grottoes, one of China''s greatest cultural treasures. These ancient caves were carved out of the rock over a period of about a thousand years, and there are more than seven hundred of them today. If you step inside and look up, you can see paintings that cover almost every part of the walls and ceilings. Many of the statues inside the caves are surprisingly lifelike, and they show elements from Ancient Greece, India and Iran. This mix is no accident. Because Dunhuang sat on the Silk Road, where East met West, artists from many lands left their mark here. The murals themselves cover an enormous area of about forty-five thousand square metres. Together, the caves are a quiet testimony to how trade and travel once brought very different cultures together in one small corner of the desert.', '说明·莫高窟', 148, '[{"q":"How long did it take to create the Mogao Grottoes?","answer":"A","options":["Roughly a thousand years.","Only a few months.","Exactly forty-five years.","Less than ten years."],"explanation":"原文 ''carved out of the rock over a period of about a thousand years'' 的转述。"},{"q":"Why do the statues mix Greek, Indian and Iranian features?","answer":"B","options":["Because foreign artists copied each other by chance.","Because it lay on the trade route that joined East and West.","Because the caves were built outside China.","Because local people disliked Chinese art."],"explanation":"原文说敦煌位于丝路、东西方相遇,各国艺术家留下印记 → 因丝路交汇。"},{"q":"What does the writer say the caves prove?","answer":"A","options":["That different cultures were once joined here through travel and trade.","That the desert was once a great sea.","That painting is harder than carving.","That the statues were made in modern times."],"explanation":"末句 ''a quiet testimony to how trade and travel once brought very different cultures together'' 的转述。"}]'::jsonb, '[{"word":"grotto","cn":"洞窟"},{"word":"carve","cn":"开凿;雕刻"},{"word":"testimony","cn":"证明"}]'::jsonb, 2, 'elective4', 'U3', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'The Flying Apsaras', 'Among all the wonderful images on the cave walls, one kind is found almost nowhere else in the world: the Apsaras, or Flying Immortals. These heavenly musicians, singers and dancers seem to float across the painted sky. In the murals they hold lotus flowers, play instruments and throw petals down towards the visitors below. Their long scarves fly out behind them, so that they look as if they are about to come down and join us. The painting of these figures was not always the same. It slowly developed over hundreds of years and finally reached a peak during the Tang Dynasty. The Tang images are especially full of life and movement. Many people believe the dancing figures reflect the confidence and optimism of the people who lived in that golden age. Today, the Flying Apsaras have become one of the best-loved symbols of Dunhuang, copied in dances, films and paintings all around the country.', '说明·飞天', 155, '[{"q":"What is special about the Apsaras?","answer":"B","options":["They are the oldest paintings in China.","They are images rarely seen anywhere else.","They were painted by foreign visitors.","They appear in only one single cave."],"explanation":"原文 ''one kind is found almost nowhere else in the world'' 的转述。"},{"q":"When did the art of painting the Apsaras reach its highest point?","answer":"C","options":["Before any caves were built.","Only in modern times.","During the Tang Dynasty.","After Dunhuang was forgotten."],"explanation":"原文 ''reached a peak during the Tang Dynasty''。"},{"q":"What do many people think the lively Tang figures show?","answer":"D","options":["The sadness of a dying city.","The fear of desert travellers.","The rules of religious painting.","The confident and hopeful spirit of that age."],"explanation":"原文 ''reflect the confidence and optimism of the people who lived in that golden age'' 的转述。"}]'::jsonb, '[{"word":"immortal","cn":"神;不朽的"},{"word":"heavenly","cn":"天国的"},{"word":"peak","cn":"顶峰"}]'::jsonb, 2, 'elective4', 'U3', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'The Library Cave', 'In 1900 something truly extraordinary happened at Dunhuang. A Taoist priest, who was clearing sand from one of the caves, suddenly found a small room that had been sealed shut for centuries. Inside were thousands of manuscripts, paintings, scrolls and even silk embroideries. This hidden room is now famous around the world as the Library Cave. The papers inside date from about the fifth century to the eleventh century, so they cover a very long stretch of history. They are so detailed that they describe the wide range of goods once carried along the Silk Road, from ceramics and medicine to perfumes and fruit. They also show how many different communities lived side by side inside this single great city. Thanks to these papers, scholars today understand far more about the trade and daily life of old Dunhuang. Yet one question is still unanswered: nobody knows for certain why the cave was sealed up in the first place.', '记叙·藏经洞', 158, '[{"q":"Who discovered the Library Cave?","answer":"A","options":["A Taoist priest clearing away sand.","A group of foreign scholars.","A famous Tang painter.","A team of modern builders."],"explanation":"原文 ''A Taoist priest, who was clearing sand… suddenly found'' 的转述。"},{"q":"Why are the papers so valuable to scholars?","answer":"B","options":["Because they are written in gold.","Because they describe the goods and communities of the old Silk Road city.","Because they are the largest in the world.","Because they were painted by the priest."],"explanation":"原文说卷轴详细记录了丝路货物与各社群生活 → 揭示当时贸易与生活。"},{"q":"What remains unknown about the Library Cave?","answer":"C","options":["Where exactly it stands.","What was kept inside it.","The real reason it was closed up.","How old the papers are."],"explanation":"末句 ''nobody knows for certain why the cave was sealed up'' 的转述。"}]'::jsonb, '[{"word":"manuscript","cn":"手稿"},{"word":"scroll","cn":"卷轴"},{"word":"seal","cn":"封闭"}]'::jsonb, 2, 'elective4', 'U3', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Dunhuang on the Silk Road', 'Long ago, Dunhuang was far more than a quiet town in the desert. It was the gateway to and from ancient China, a green oasis where tired travellers could finally rest. As soon as a caravan reached the city, traders could buy food, water and a safe place to sleep before moving on. Because the Silk Road passed straight through it, Dunhuang became a busy meeting point where merchants from East and West did business together. Goods arrived from places as far away as North-east Europe, and Chinese goods were sent out across Asia and Europe in return. This trade made the city both rich and famous. Yet Dunhuang was never only about money. Along with silk and spices, new ideas, religions, music and art also travelled the road. In this way the small desert city grew into one of the most important centres of cultural exchange in the whole ancient world.', '说明·丝路上的敦煌', 152, '[{"q":"What could traders do as soon as they reached Dunhuang?","answer":"D","options":["Sell their camels at once.","Cross the sea by boat.","Visit the painted caves for free.","Buy supplies and rest somewhere safe before moving on."],"explanation":"原文 ''traders could buy food, water and a safe place to sleep'' 的转述。"},{"q":"Why did Dunhuang become such a busy meeting point?","answer":"A","options":["Because the Silk Road ran right through it.","Because it had the tallest buildings.","Because no other towns existed nearby.","Because the weather was always cool."],"explanation":"原文 ''Because the Silk Road passed straight through it'' 的转述。"},{"q":"Besides goods, what else travelled along the road?","answer":"B","options":["Only gold and silver.","Fresh ideas, faiths, music and other arts.","Nothing at all but silk.","Soldiers and weapons only."],"explanation":"原文 ''new ideas, religions, music and art also travelled the road'' 的转述。"}]'::jsonb, '[{"word":"gateway","cn":"门户"},{"word":"oasis","cn":"绿洲"},{"word":"merchant","cn":"商人"}]'::jsonb, 2, 'elective4', 'U3', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'From Decline to New Life', 'Dunhuang did not stay at the top forever. During the Ming Dynasty the main trade routes changed, and ships began to carry many goods by sea instead. Although the city had once been so prosperous, it slowly grew quieter and less important. Over time it almost faded from memory, even though it still held priceless treasures inside its caves. For centuries Dunhuang waited, half forgotten by the wider world. Then, in our own century, its story took a happy turn. The Belt and Road Initiative has helped to bring the old Silk Road back to life, and Dunhuang has once again become a global crossroads. In 2017 the city hosted hundreds of guests from more than fifty countries for a great cultural Expo. The theme of that event was to promote exchange and strengthen mutual cooperation between nations along the route. After so long, the desert city is busy and welcoming once more.', '说明·敦煌的衰落与复兴', 153, '[{"q":"Why did Dunhuang become less important during the Ming Dynasty?","answer":"C","options":["Because the caves were destroyed.","Because its people moved abroad.","Because trade moved to sea routes.","Because the desert disappeared."],"explanation":"原文 ''the main trade routes changed, and ships began to carry many goods by sea'' 的转述。"},{"q":"What has helped bring the city back to life today?","answer":"D","options":["A new river through the desert.","The closing of all the caves.","A move away from cultural exchange.","A modern plan to bring the ancient route back to life."],"explanation":"原文 ''The Belt and Road Initiative has helped to bring the old Silk Road back to life'' 的转述。"},{"q":"What was the aim of the 2017 Expo?","answer":"A","options":["To encourage exchange and cooperation between nations.","To sell the city''s treasures.","To keep foreign guests away.","To end the Silk Road for good."],"explanation":"原文 ''to promote exchange and strengthen mutual cooperation between nations'' 的转述。"}]'::jsonb, '[{"word":"prosperous","cn":"繁荣的"},{"word":"crossroads","cn":"汇集地"},{"word":"mutual","cn":"相互的"}]'::jsonb, 2, 'elective4', 'U3', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Protecting Dunhuang''s Treasures', 'The paintings of Dunhuang have survived for more than a thousand years, but they are far more fragile than they look. Light, damp air and even the breath of too many visitors can slowly damage the ancient colours. Because of this, the people who care for the caves work hard to protect them. They keep the light inside very low so that the murals do not fade, and they limit how many tourists may enter each cave every day. In recent years, experts have also begun to copy the caves in a new way. Using cameras and computers, they make careful digital pictures of every wall, in order that future students can study the art without harming it. Visitors can now explore some caves on a screen before stepping inside the real ones. In this way, Dunhuang is being shared with the whole world while its precious treasures are kept safe for those who come after us.', '说明·守护敦煌', 157, '[{"q":"Why are the murals at risk even now?","answer":"B","options":["Visitors paint over them.","Light, damp air and crowds can slowly harm the colours.","They were never finished.","The caves are too cold."],"explanation":"原文 ''Light, damp air and even the breath of too many visitors can slowly damage the ancient colours'' 的转述。"},{"q":"What do the cave keepers do to protect the paintings?","answer":"C","options":["Turn the lights up bright.","Allow everyone in at once.","Keep the light low and limit daily visitors.","Move the murals outdoors."],"explanation":"原文 ''keep the light inside very low… limit how many tourists may enter'' 的转述。"},{"q":"Why do experts make digital pictures of the caves?","answer":"D","options":["To sell the photos for money.","To replace the real caves forever.","Because the caves will soon close.","To let later learners study the paintings without harm."],"explanation":"原文 ''in order that future students can study the art without harming it'' 的转述。"}]'::jsonb, '[{"word":"fragile","cn":"脆弱的"},{"word":"fade","cn":"褪色"},{"word":"digital","cn":"数字的"}]'::jsonb, 2, 'elective4', 'U3', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U3', 'My First Visit to Dunhuang', 'Last summer my family travelled to Dunhuang, a city on the edge of the (1)____. I had read about its caves, but seeing them was even better than I had (2)____. Our guide led us through the dark grottoes and asked us to look (3)____ at the painted ceilings. The colours were so bright that I could hardly (4)____ they were a thousand years old. In one cave we saw the famous Flying Apsaras, who seemed to (5)____ across the sky. The guide explained that Dunhuang had once been an important (6)____ on the Silk Road. Because so many traders passed through, the city grew (7)____ and full of art from many lands. Before we left, I bought a small (8)____ of a dancing Apsara to take home. That day I learned that history can be (9)____ as well as beautiful. I will never (10)____ my first visit to the desert city.', 152, 2, '[{"q":"1","answer":"A","options":["desert","ocean","forest","river"],"explanation":"敦煌位于沙漠边缘,后文又称 desert city → desert。"},{"q":"2","answer":"B","options":["forgotten","imagined","sold","lost"],"explanation":"better than I had imagined 比想象的还好 → imagined。"},{"q":"3","answer":"C","options":["away","back","up","out"],"explanation":"look up at the ceilings 抬头看天花板 → up。"},{"q":"4","answer":"D","options":["buy","hear","count","believe"],"explanation":"could hardly believe 难以相信 → believe。"},{"q":"5","answer":"A","options":["float","fall","sleep","swim"],"explanation":"seemed to float across the sky 仿佛在天空飘浮 → float。"},{"q":"6","answer":"B","options":["shop","stop","farm","garden"],"explanation":"an important stop on the Silk Road 丝路上重要的一站 → stop。"},{"q":"7","answer":"C","options":["poor","empty","rich","quiet"],"explanation":"the city grew rich 城市变得富裕 → rich。"},{"q":"8","answer":"D","options":["problem","mistake","noise","picture"],"explanation":"a small picture of a dancing Apsara 一张飞天小画 → picture。"},{"q":"9","answer":"A","options":["exciting","boring","silent","empty"],"explanation":"history can be exciting 历史可以很精彩 → exciting。"},{"q":"10","answer":"B","options":["sell","forget","lose","break"],"explanation":"never forget my first visit 永远不会忘记 → forget。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U3', 'How the Murals Were Made', 'The murals of Dunhuang were not painted in a single day. First, workers had to (1)____ the rough rock walls until they were smooth. Then artists drew the main lines (2)____ a thin brush. They made their own colours from stones and plants, (3)____ some of these colours have lasted for over a thousand years. The work was slow and difficult, (4)____ the artists were very patient. Today these ancient paintings are extremely (5)____, so the people who look after them must be careful. Bright light can make the colours (6)____, and damp air can harm the walls. For this (7)____, only a small number of visitors may enter each cave every day. Experts also use cameras to make digital (8)____ of every wall. In this way, students can (9)____ the art on a screen without harming the real caves. Thanks to their hard work, the murals will be kept (10)____ for many years to come.', 156, 2, '[{"q":"1","answer":"C","options":["sell","open","clean","lose"],"explanation":"clean the rough rock walls 清理粗糙的岩壁 → clean。"},{"q":"2","answer":"D","options":["for","from","about","with"],"explanation":"draw lines with a brush 用刷子画线 → with。"},{"q":"3","answer":"A","options":["so","but","or","although"],"explanation":"前因后果:so some colours have lasted → so。"},{"q":"4","answer":"B","options":["so","but","or","because"],"explanation":"工作艰难“但”画师有耐心,转折 → but。"},{"q":"5","answer":"C","options":["cheap","heavy","fragile","loud"],"explanation":"extremely fragile 极其脆弱 → fragile。"},{"q":"6","answer":"D","options":["grow","rise","sing","fade"],"explanation":"light can make the colours fade 使颜色褪去 → fade。"},{"q":"7","answer":"A","options":["reason","price","song","game"],"explanation":"For this reason 因此 → reason。"},{"q":"8","answer":"B","options":["mistakes","copies","noises","prices"],"explanation":"digital copies of every wall 每面墙的数字副本 → copies。"},{"q":"9","answer":"C","options":["break","sell","study","lose"],"explanation":"students can study the art 学生可以研究艺术 → study。"},{"q":"10","answer":"D","options":["dirty","dark","cold","safe"],"explanation":"kept safe for many years 妥善保存许多年 → safe。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U3', 'A Trader on the Silk Road', 'My name is Anir, and for many years I have been a trader on the Silk (1)____. Each spring I load my camels with silk and tea and begin the long (2)____ west. The desert is hard and dry, so I always carry plenty of (3)____ with me. (4)____ I reach the oasis of Dunhuang, I feel safe at last. There I can rest, feed my animals, and (5)____ my goods for spices and glass from the West. The market is always (6)____ with people from many different lands. In the evenings, traders share stories around the fire, and I have learned a few (7)____ of several languages. Dunhuang is more than a place to do (8)____; it is where East and West truly meet. (9)____ the journey is dangerous, I would not give it up. Every time I see the green trees of the oasis (10)____ of me, I know that all the hard miles were worth it.', 159, 2, '[{"q":"1","answer":"A","options":["Road","Sea","Sky","Hill"],"explanation":"the Silk Road 丝绸之路 → Road。"},{"q":"2","answer":"B","options":["dinner","journey","lesson","sleep"],"explanation":"the long journey west 漫长的西行 → journey。"},{"q":"3","answer":"C","options":["sand","gold","water","paper"],"explanation":"干旱沙漠中携带充足的水 → water。"},{"q":"4","answer":"D","options":["Unless","Although","Because","When"],"explanation":"到达绿洲“时”感到安全,时间关系 → When。"},{"q":"5","answer":"A","options":["exchange","lose","break","hide"],"explanation":"exchange my goods for spices 拿货物换香料 → exchange。"},{"q":"6","answer":"B","options":["empty","busy","quiet","closed"],"explanation":"the market is always busy 集市总是热闹 → busy。"},{"q":"7","answer":"C","options":["songs","coins","words","maps"],"explanation":"a few words of several languages 几种语言的几个词 → words。"},{"q":"8","answer":"D","options":["harm","damage","sport","business"],"explanation":"a place to do business 做生意的地方 → business。"},{"q":"9","answer":"A","options":["Although","Because","Unless","Until"],"explanation":"旅程危险“尽管”如此也不放弃,让步 → Although。"},{"q":"10","answer":"B","options":["instead","ahead","afraid","proud"],"explanation":"the oasis ahead of me 前方的绿洲 → ahead。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U3', 'Mingsha Mountain and Crescent Lake', 'Just outside Dunhuang there is a famous (1)____ called Mingsha Mountain, made entirely of soft yellow sand. Many visitors climb to the top to watch the (2)____ go down over the desert. The view from up there is so beautiful that people fall (3)____ love with it at once. At the foot of the mountain lies Crescent Lake, a small pool of clear water (4)____ has never dried up, even in the hot desert. Local people say the lake is shaped (5)____ a new moon. In the early morning, before the day grows too (6)____, you can ride a camel across the sand. The animals walk slowly and steadily, (7)____ you feel quite safe on their backs. Some travellers stay until night (8)____, just to see the bright stars above the quiet dunes. (9)____ you ever go to Dunhuang, do not miss this magical place. It is a part of the desert (10)____ you will remember for the rest of your life.', 162, 2, '[{"q":"1","answer":"C","options":["river","market","hill","bridge"],"explanation":"沙堆成的山,a famous hill → hill。"},{"q":"2","answer":"D","options":["rain","snow","wind","sun"],"explanation":"watch the sun go down 看落日 → sun。"},{"q":"3","answer":"A","options":["in","out","off","down"],"explanation":"fall in love with 爱上 → in。"},{"q":"4","answer":"B","options":["who","that","where","why"],"explanation":"先行词 water、从句缺主语 → that。"},{"q":"5","answer":"C","options":["for","with","like","by"],"explanation":"shaped like a new moon 形如新月 → like。"},{"q":"6","answer":"D","options":["cold","dark","wet","hot"],"explanation":"沙漠白天太热,before the day grows too hot → hot。"},{"q":"7","answer":"A","options":["so","but","or","although"],"explanation":"走得平稳,“所以”你很安全,结果 → so。"},{"q":"8","answer":"B","options":["opens","falls","sells","wins"],"explanation":"stay until night falls 待到夜幕降临 → falls。"},{"q":"9","answer":"C","options":["Unless","Although","If","Because"],"explanation":"如果你去敦煌,别错过此地,条件 → If。"},{"q":"10","answer":"D","options":["when","why","how","that"],"explanation":"先行词 part、从句缺宾语 → that。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U3', 'My Grandmother the Guide', 'My grandmother has been a volunteer (1)____ at the Mogao Grottoes for over twenty years. Every weekend she leads small groups of visitors through the dark caves and tells them the old (2)____ behind each painting. She always speaks softly, (3)____ loud voices and bright lights can harm the fragile murals. People come from all over the world, (4)____ many of them do not speak Chinese. To help them, my grandmother has learned to explain things in simple (5)____. She loves her work because it lets her (6)____ the beauty of Dunhuang with others. (7)____ a tour ends, the visitors often thank her warmly. Last month a foreign student told her that the caves were the most (8)____ thing he had ever seen. My grandmother smiled and said that was the best (9)____ she could ever receive. She hopes that more young people will come to (10)____ the great art of their own country.', 154, 2, '[{"q":"1","answer":"A","options":["guide","driver","cook","farmer"],"explanation":"a volunteer guide 义务讲解员 → guide。"},{"q":"2","answer":"B","options":["prices","stories","games","songs"],"explanation":"the old stories behind each painting 每幅画背后的故事 → stories。"},{"q":"3","answer":"C","options":["although","unless","because","so that"],"explanation":"轻声说话“因为”大声会损害壁画,原因 → because。"},{"q":"4","answer":"D","options":["so","or","for","but"],"explanation":"世界各地的人,“但”很多不说中文,转折 → but。"},{"q":"5","answer":"A","options":["words","money","metres","hours"],"explanation":"explain things in simple words 用简单的话解释 → words。"},{"q":"6","answer":"B","options":["sell","share","hide","break"],"explanation":"share the beauty with others 与人分享美 → share。"},{"q":"7","answer":"C","options":["Unless","Although","When","Because"],"explanation":"参观结束“时”游客道谢,时间 → When。"},{"q":"8","answer":"D","options":["boring","ugly","empty","wonderful"],"explanation":"the most wonderful thing 最美妙的东西 → wonderful。"},{"q":"9","answer":"A","options":["gift","mistake","problem","price"],"explanation":"the best gift she could receive 最好的礼物 → gift。"},{"q":"10","answer":"B","options":["forget","appreciate","waste","lose"],"explanation":"appreciate the great art 欣赏伟大的艺术 → appreciate。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U3', 'Sharing Chinese Culture', 'More and more people around the world want to learn about Chinese (1)____. To help them, China has opened many Confucius Institutes abroad. These institutes teach the Chinese (2)____ and also hold art shows, talks and film festivals. (3)____ a student joins, he or she can learn not only the words but also the ideas behind them. Many learners say that studying the language helps them (4)____ Chinese culture far more deeply. (5)____ the lessons are sometimes difficult, the students rarely give up. One teacher told me that his happiest (6)____ was watching shy learners grow confident. (7)____ he teaches Chinese, he feels that he is building a small bridge between two (8)____. Cultural exchange, he says, should travel in both (9)____, so that each side can learn from the other. (10)____ such work continues, friendship between nations will surely grow stronger year by year.', 145, 2, '[{"q":"1","answer":"C","options":["weather","money","culture","sport"],"explanation":"learn about Chinese culture 了解中国文化 → culture。"},{"q":"2","answer":"D","options":["food","clothes","coins","language"],"explanation":"teach the Chinese language 教汉语 → language。"},{"q":"3","answer":"A","options":["When","Unless","Although","Because"],"explanation":"学生加入“时”能学到思想,时间 → When。"},{"q":"4","answer":"B","options":["forget","understand","waste","sell"],"explanation":"helps them understand Chinese culture 帮助理解中国文化 → understand。"},{"q":"5","answer":"C","options":["Because","Unless","Although","As soon as"],"explanation":"课程虽难,学生很少放弃,让步 → Although。"},{"q":"6","answer":"D","options":["price","mistake","noise","moment"],"explanation":"his happiest moment 他最快乐的时刻 → moment。"},{"q":"7","answer":"A","options":["Because","Although","Unless","Until"],"explanation":"“因为”教汉语,他觉得在架桥,原因 → Because。"},{"q":"8","answer":"B","options":["prices","cultures","machines","gardens"],"explanation":"a bridge between two cultures 两种文化间的桥 → cultures。"},{"q":"9","answer":"C","options":["colours","prices","directions","sizes"],"explanation":"travel in both directions 双向流动 → directions。"},{"q":"10","answer":"D","options":["Although","Unless","Even though","As long as"],"explanation":"“只要”工作继续,友谊就会更牢,条件 → As long as。"}]'::jsonb, 6, 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U3 听力·对话 Planning a Trip to Dunhuang', '外研社版选择性必修第四册 U3 · dialogue', 3, 'Mia: Have you decided where to go for the summer holiday, Tom?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U3 听力·短文 About the Mogao Grottoes', '外研社版选择性必修第四册 U3 · passage', 2, 'The Mogao Grottoes lie near the city of Dunhuang.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U3 听力·对话 Looking at the Flying Apsaras', '外研社版选择性必修第四册 U3 · dialogue', 3, 'Guide: Now look up at the wall in front of you. Can you see the flying figures?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U3 听力·短文 The Library Cave', '外研社版选择性必修第四册 U3 · passage', 2, 'In 1900, a Taoist priest made an amazing discovery at Dunhuang.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U3 听力·对话 East Meets West', '外研社版选择性必修第四册 U3 · dialogue', 3, 'Lily: Our history teacher said Dunhuang was a meeting point of East and West. Why?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U3 听力·短文 Advice for Visitors', '外研社版选择性必修第四册 U3 · passage', 2, 'If you plan to visit the Dunhuang caves, here is some useful advice.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (12, 'Recommend a Chinese Cultural Place to a Foreign Friend(向外国朋友推荐一处中国文化胜地)', 'An Email of Recommendation', '假设你叫李华,你的美国朋友 Selena 计划寒假来中国旅行,想找一处兼具乐趣与传统文化的地方。请用英语给她写一封约100词的回信,内容包括:① 推荐一处文化胜地(如敦煌);② 说明它的特别之处;③ 给出两条推荐理由。注意:恰当使用状语从句(when/if/because/so that/although 等)使行文连贯。', 'Suppose you are Li Hua. Your American friend Selena plans to travel in China during the winter vacation and wants a place full of both fun and traditional culture. Write a reply email (about 100 words) including: 1) recommend one place of cultural highlights (e.g. Dunhuang); 2) say what is special about it; 3) give two reasons for your recommendation. Use adverbial clauses (when / if / because / so that / although) to link your ideas.', '["明确推荐一处地点(I''d strongly recommend …)","说明其特别之处(What makes it special is …)","给出至少两条理由,用状语从句串联(because … / so that …)","得体的邮件开头与结尾 + 状语从句衔接连贯"]'::jsonb, 70, 100, 'Dear Selena,
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (12, 'elective4', 'U3', '{"title":"状语从句综合复习·连词速查","intro":"状语从句用一个连词把“时间、条件、让步、原因、结果、目的、方式”等信息接到主句上。判断口诀:先看主句和从句之间是哪种逻辑关系,再选对应的连词;同一类里的连词意思相近,但不同类绝不能混用。","table":{"headers":["关系","常用连词","例句"],"rows":[["时间","when / while / as / until / before / after / as soon as","When you look up, you can see the murals."],["条件","if / unless / as long as / in case","If the weather is good, we will climb the sand mountain."],["让步","although / though / even though / while","Although it sits in the desert, it is rich in culture."],["原因","because / since / as / now that","Since the Silk Road passed through it, Dunhuang grew rich."],["结果","so + 形/副 + that;such + (a/an) + 名 + that","The cave was so dark that we could hardly see."],["目的","so that / in order that","Come closer so that you can see the details."],["方式","as if / as though","The figures look as if they are floating."]]},"specialRules":[{"rule":"so 接形容词/副词,such 接名词:so beautiful that… / such a city that…","mark":"so + adj + that / such + a + n + that"},{"rule":"unless = if…not,本身已含否定,从句不再加 not","mark":"Unless you book a ticket, you can''t enter."},{"rule":"in case = 以防(万一),后接“可能发生的情况”,不表“如果就一定”","mark":"Take water in case you feel thirsty."},{"rule":"although / though 不能与 but 连用;but 与 although 二选一","mark":"Although…, …(无 but)"},{"rule":"as if / as though 后既可用陈述语气,也可用虚拟(were)表与事实相反","mark":"looked as if it were a dream"}],"why":["状语从句考的不是语法术语,而是“逻辑选词”:同样的两个分句,换一个连词意思就全变了。先想清楚是“因为、虽然、只要、以便、仿佛”中的哪一种,再下笔,答案自然唯一。"],"gaokaoPoints":["语法填空/完形高频:由句子逻辑判断 when/if/unless/although/because/so that 等连词。","so…that 与 such…that 辨析(看后面接形容词还是名词)。","易混:while 既可表“当…时”(时间),也可表“尽管/而”(让步对比);as 既表“随着/当…时”,也表“因为”,需看上下文。"],"examVsReal":[{"exam":"Although it is far, it is worth visiting.(考试要求完整连词)","real":"It''s far, but so worth visiting!","note":"口语里常用 but/though 放句末,书面考试更爱句首 although。"},{"exam":"I''ll go early so that I can see the sunrise.(目的状语从句)","real":"I''ll go early to catch the sunrise.","note":"口语常用不定式 to do 表目的,更简洁;考试爱考 so that 从句。"}]}'::jsonb, 'fltrp');
